  ('fluffy-bunny-tail-plugs', 'Bunny Tail Plug', 'bdsm', 'FAUX FUR TAIL', 18000, 'FAUX FUR TAIL', '/assets/IMG_0283.webp', 'An ultra-soft plush faux-fur pom-pom bunny tail mounted to an ergonomically tapered plug. Available in silky liquid silicone stems and mirror-polished stainless steel stems capped with sparkling base jewels.', ARRAY['Tail Material: Hypoallergenic Ultra-Soft Faux Fur Pom-Pom', 'Shaft Material: Medical Silicone / Mirror Stainless Steel', 'Base: Ergonomic Flared Anchor with Embedded Crystal']::text[], '[{"name":"Scarlet Fur (Silicone)","price":18000,"priceStr":"₦18,000","img":"/assets/IMG_0283.webp"},{"name":"Noir Fur (Silicone)","price":18000,"priceStr":"₦18,000","img":"/assets/IMG_0284.webp"},{"name":"Violet Fur (Chrome Gem)","price":20000,"priceStr":"₦20,000","img":"/assets/IMG_0286.webp"},{"name":"Blush Fur (Chrome Gem)","price":20000,"priceStr":"₦20,000","img":"/assets/IMG_0288.webp"}]'::jsonb, true),
